import os
from .base_config import EditableConfig


class SCF(EditableConfig):
    """Site Configuration File class"""

    def __init__(self, project, name, scf_params=None,
                 scf_dir='/opt/nokia/SS_MzOam/cloud-siteoam/siteoam/site_conf'):
        """
        Class SCF is responsible for initializing parameters of configuration SCF.
        :param project: project name
        :param name: full name of the project file
        :param scf_params: parameters needed to connection, for example; ip address, username, password
        :param scf_dir directory with scf file
        """

        super(SCF, self).__init__(path=None)

        self.dir_path = os.path.join(scf_dir, project)
        self.filename = name
        self.path = os.path.join(self.dir_path, self.filename)
        self._set_attr('scf_params', scf_params or [])

